#pragma once
/// \file
/// The authoritative, saved PROJECT DOCUMENT (ARCHITECTURE.md sections 5-6). Plain value
/// types: copying a Project is a complete snapshot (parameter graphs are copy-on-write, so a
/// copy is cheap). Nothing here is derived data; the domain::Model, reports, drawings and
/// cutting plans are always regenerated by resolve() (resolve.hpp). All lengths are mm.
#include "fos/cutting/types.hpp"
#include "fos/drawings/edits.hpp"
#include "fos/formats/json.hpp"
#include "fos/furniture/definition.hpp"
#include "fos/furniture/panel.hpp"
#include "fos/furniture/templates.hpp"
#include "fos/production/reports.hpp"

#include <map>
#include <string>
#include <variant>
#include <vector>

namespace fos::project {

/// Descriptive data of a project. Timestamps are supplied by the caller (the core never reads
/// the clock), as ISO-8601 UTC text "YYYY-MM-DDTHH:MM:SSZ" or empty. Units are always "mm".
struct Metadata {
    std::string id;          ///< UUID v4 of the project; non-empty.
    std::string name;
    std::string description;
    std::string author;
    std::string currency = "EUR"; ///< Currency of all costs in the libraries (ISO 4217 code by convention).
    std::string createdAt;
    std::string modifiedAt;
    formats::Json extra = formats::Json::object(); ///< Unknown keys of the file object (preserved).
};

/// A free-standing parametric panel placed as its own assembly (one part).
struct PanelItem {
    domain::AssemblyId id;          ///< Id of the generated assembly (= item id).
    geometry::Transform placement;  ///< Assembly frame -> project frame.
    furniture::PanelDefinition panel; ///< panel.name is the item name; panel.id the part id.
};

/// One furniture item of the project: a parametric cabinet or a free panel.
struct Item {
    std::variant<furniture::CabinetDefinition, PanelItem> definition;
    formats::Json extra = formats::Json::object(); ///< Unknown keys of the file object (preserved).

    const std::string& id() const;
    const std::string& name() const;
    const geometry::Transform& placement() const;
    bool isCabinet() const noexcept { return definition.index() == 0; }
    furniture::CabinetDefinition* cabinet() noexcept { return std::get_if<0>(&definition); }
    const furniture::CabinetDefinition* cabinet() const noexcept { return std::get_if<0>(&definition); }
    PanelItem* panel() noexcept { return std::get_if<1>(&definition); }
    const PanelItem* panel() const noexcept { return std::get_if<1>(&definition); }
};

/// A leftover board listed as extra stock for one material (cutting).
struct Remnant {
    std::string id;     ///< Unique within its material; non-empty.
    std::string label;
    double length = 0;  ///< Along the sheet length (grain direction of grained boards), mm, > 0.
    double width = 0;   ///< mm, > 0.
    int quantity = 1;   ///< >= 1.
};

/// Shop settings of the cutting optimiser for one material (or the project default).
struct CuttingSettings {
    double kerf = 4.0;
    cutting::Trim trim{10.0, 10.0, 10.0, 10.0};
    double minRemnantLength = 300.0;
    double minRemnantWidth = 100.0;
    int maxStages = 0; ///< 0 = unlimited, otherwise >= 2.
    cutting::FirstCut firstCut = cutting::FirstCut::Free;
    cutting::Objective objective = cutting::Objective::MinimizeSheets;
    std::vector<Remnant> remnants; ///< Extra stock, opened before full sheets.
};

struct ProjectCuttingSettings {
    CuttingSettings defaults;                          ///< Materials without an own entry.
    std::map<std::string, CuttingSettings> materials;  ///< Keyed by material id.

    /// Entry for `materialId`, or `defaults`.
    const CuttingSettings& forMaterial(const std::string& materialId) const;
};

/// Project-wide settings used by the convenience outputs and saving.
struct ProjectSettings {
    int backupCount = 3;                              ///< Rotating `.bakN` files kept on save (>= 0).
    production::EdgeBandingOptions edgeBanding;       ///< Overhang / waste of the edge banding report.
    bool cutListGroupAcrossAssemblies = true;         ///< production::CutListOptions::groupAcrossAssemblies.
    formats::Json extra = formats::Json::object();    ///< Unknown keys of the file object (preserved).
};

struct Project {
    Metadata metadata;
    furniture::Libraries libraries;  ///< Materials, edge bands, hardware catalogue.
    std::vector<Item> items;         ///< Project order (= assembly order of the resolved model).
    /// User edits of generated drawings, keyed by drawing id (see assemblyDrawingId()).
    std::map<std::string, drawings::DrawingEdits> drawingEdits;
    ProjectCuttingSettings cutting;
    ProjectSettings settings;
    formats::Json custom = formats::Json::object(); ///< User JSON object, preserved verbatim.
    formats::Json extra = formats::Json::object();  ///< Unknown payload keys (preserved).

    const Item* findItem(const std::string& id) const;
    Item* findItem(const std::string& id);
};

/// Drawing id of the assembly drawing of item `itemId`: "<itemId>/drawing.assembly".
std::string assemblyDrawingId(const std::string& itemId);
/// Drawing id of the part drawing of part `partId`: "<partId>/drawing.part".
std::string partDrawingId(const std::string& partId);

/// Ids of the generic default libraries of a new project. They are GENERIC placeholders
/// (no manufacturer, cost 0 = unknown), not real products.
namespace defaults {
inline constexpr const char* kParticleboard18 = "mat.generic.pb18";
inline constexpr const char* kMdf18 = "mat.generic.mdf18";
inline constexpr const char* kHdf3 = "mat.generic.hdf3";
inline constexpr const char* kAbs2 = "eb.generic.abs2";
inline constexpr const char* kAbs04 = "eb.generic.abs04";
} // namespace defaults

/// Generic default materials: particleboard 18, MDF 18, HDF 3 (2800 x 2070 mm, cost 0).
std::vector<domain::Material> defaultMaterials();
/// Generic default edge bands: ABS 2 x 22 and ABS 0.4 x 22 (cost 0).
std::vector<domain::EdgeBand> defaultEdgeBands();

/// New empty project: given metadata, default libraries (defaultMaterials(), defaultEdgeBands(),
/// hardware::builtinCatalog()), no items, default settings.
Project newProject(Metadata metadata);

/// Template materials referring to the default libraries: carcass pb18, back hdf3, front =
/// carcass, visible edge abs2, hidden edge abs04.
furniture::templates::TemplateMaterials defaultTemplateMaterials();

} // namespace fos::project
